ckup', this)"><span class="request-filter-label">Ready for pickup</span><span class="request-filter-count">0</span></button><button type="button" class="request-filter" data-filter-status="Completed" data-filter-label="Completed" aria-pressed="false" data-action-click="setAdminRequestFilter('Completed', this)"><span class="request-filter-label">Completed</span><span class="request-filter-count">0</span></button><button type="button" class="request-filter" data-filter-status="Rejected" data-filter-label="Rejected" aria-pressed="false" data-action-click="setAdminRequestFilter('Rejected', this)"><span class="request-filter-label">Rejected</span><span class="request-filter-count">0</span></button></div></div>
